'use strict';

/**
* Calculate the Lanczos sum for the approximation of the gamma function for single-precision floating-point number.
*
* @module @stdlib/math/base/special/gamma-lanczos-sumf
*
* @example
* var gammaLanczosSumf = require( '@stdlib/math/base/special/gamma-lanczos-sumf' );
*
* var v = gammaLanczosSumf( 4.0 );
* // returns ~950.366
*
* v = gammaLanczosSumf( -1.5 );
* // returns ~1373366.245
*
* v = gammaLanczosSumf( -0.5 );
* // returns ~-699841.735
*
* v = gammaLanczosSumf( 0.5 );
* // returns ~96074.186
*
* v = gammaLanczosSumf( 0.0 );
* // returns Infinity
*
* v = gammaLanczosSumf( NaN );
* // returns NaN
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
